from enum import Enum
class ExecutiveErrorCode(str,Enum):
    INVALID_EXECUTIVE_REQUEST="INVALID_EXECUTIVE_REQUEST";GOAL_REQUIRED="GOAL_REQUIRED";GOAL_AMBIGUOUS="GOAL_AMBIGUOUS";CONSTRAINT_CONFLICT="CONSTRAINT_CONFLICT";PLAN_DEPENDENCY_CYCLE="PLAN_DEPENDENCY_CYCLE";PLAN_LIMIT_EXCEEDED="PLAN_LIMIT_EXCEEDED";UNSUPPORTED_ACTION_CATEGORY="UNSUPPORTED_ACTION_CATEGORY";UNKNOWN_CAPABILITY="UNKNOWN_CAPABILITY";HARD_CONSTRAINT_VIOLATION="HARD_CONSTRAINT_VIOLATION";POLICY_BLOCKED="POLICY_BLOCKED";APPROVAL_REQUIRED="APPROVAL_REQUIRED";BUDGET_UNKNOWN="BUDGET_UNKNOWN";BUDGET_LIMIT_EXCEEDED="BUDGET_LIMIT_EXCEEDED";COGNITIVE_CONTEXT_INSUFFICIENT="COGNITIVE_CONTEXT_INSUFFICIENT";COUNCIL_CONTEXT_INSUFFICIENT="COUNCIL_CONTEXT_INSUFFICIENT";PLAN_REVISION_CONFLICT="PLAN_REVISION_CONFLICT"
class ExecutionErrorCode(str,Enum):
    INVALID_EXECUTION_REQUEST="INVALID_EXECUTION_REQUEST";PLAN_NOT_FOUND="PLAN_NOT_FOUND";PLAN_VERSION_MISMATCH="PLAN_VERSION_MISMATCH";PROPOSAL_NOT_FOUND="PROPOSAL_NOT_FOUND";APPROVAL_NOT_FOUND="APPROVAL_NOT_FOUND";APPROVAL_INVALID="APPROVAL_INVALID";APPROVAL_EXPIRED="APPROVAL_EXPIRED";APPROVAL_REVOKED="APPROVAL_REVOKED";APPROVAL_SCOPE_MISMATCH="APPROVAL_SCOPE_MISMATCH";CAPABILITY_NOT_FOUND="CAPABILITY_NOT_FOUND";CAPABILITY_DISABLED="CAPABILITY_DISABLED";CAPABILITY_DEGRADED="CAPABILITY_DEGRADED";RUNTIME_POLICY_BLOCK="RUNTIME_POLICY_BLOCK";RISK_ESCALATED="RISK_ESCALATED";BUDGET_EXCEEDED="BUDGET_EXCEEDED";DEPENDENCY_NOT_SATISFIED="DEPENDENCY_NOT_SATISFIED";CHECKPOINT_NOT_SATISFIED="CHECKPOINT_NOT_SATISFIED";IDEMPOTENCY_CONFLICT="IDEMPOTENCY_CONFLICT";EXECUTION_FAILED="EXECUTION_FAILED";VERIFICATION_FAILED="VERIFICATION_FAILED";UNKNOWN_OUTCOME="UNKNOWN_OUTCOME";RETRY_NOT_ALLOWED="RETRY_NOT_ALLOWED";ROLLBACK_FAILED="ROLLBACK_FAILED";CIRCUIT_OPEN="CIRCUIT_OPEN";REPLAN_REQUIRED="REPLAN_REQUIRED"
class ExecutionError(Exception):
    def __init__(self,code:ExecutionErrorCode,message:str):self.code=code;super().__init__(message)
class ExecutiveError(Exception):
    def __init__(self,code:ExecutiveErrorCode,message:str):self.code=code;super().__init__(message)
